// One-off generator: mirrors flavour-engine.mjs (the canonical shared
// source) into shared/flavour-engine.js, a plain non-module <script> the
// three browser tools (notes-factory, long-post-factory, update-factory)
// load directly — so there is exactly one hand-maintained copy of the
// flavour definitions and selection logic, never three. Re-run this any
// time flavour-engine.mjs changes; do not hand-edit the generated file.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const src = fs.readFileSync(path.join(__dirname, 'flavour-engine.mjs'), 'utf8');

// Strip `export ` keywords (the only ESM-specific syntax this file uses) —
// everything else is plain JS, safe to run as-is in a non-module <script>.
const body = src.replace(/^export /gm, '');

const out = `// AUTO-GENERATED by gen-flavour-engine-browser.mjs from
// Automation/core/src/flavour-engine.mjs. Do not hand-edit — re-run the
// generator instead so this never drifts from the canonical source.
// Exposes window.FlavourEngine = { FLAVOUR_ENGINE, selectFlavour,
// buildFlavourPromptBlock, selectOpeningStyle, buildEditorialVarietyBlock }.
(function(global){
${body}
global.FlavourEngine = { FLAVOUR_ENGINE, selectFlavour, buildFlavourPromptBlock, selectOpeningStyle, buildEditorialVarietyBlock };
})(typeof window !== 'undefined' ? window : this);
`;

const outDir = path.join(REPO_ROOT, 'shared');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'flavour-engine.js'), out);
console.log('wrote shared/flavour-engine.js');
